 function select(c){draft=clone(c);placementSide=c.kind==='npc'?'foe':'friend';builderErrors=[];show('review');}
 function drawRoster(){para(main,'Your reusable character collection. Import a sheet or build an SRD adventurer, review it, then add it to the table. Stored in this browser; export a copy for another device.');const actions=el('div',undefined,'char-actions');actions.append(button('Import a character',()=>show('import')),button('Build a character',()=>show('build')),button('Export collection',()=>download('isles-characters.json',{format:'isles-character-collection/1',characters:roster})));main.append(actions);if(!roster.length)para(main,'No saved characters yet.');for(const c of roster){const row=el('article',undefined,'char-card');const im=el('img');im.src=tokens.find(t=>t.id===c.token_id)?.path??'';im.alt='';const text=el('div');text.append(el('h3',c.name));para(text,[c.species,c.classes?.map(c=>c.name+(c.level?' '+c.level:'')).join(' / '),c.kind==='npc'?'NPC':'PC'].filter(Boolean).join(' · '));para(text,`${c.combat.hp_max} HP · AC ${c.combat.ac} · ${c.combat.speed} ft`);row.append(im,text,button('Open sheet',()=>select(c)));main.append(row);}}
 async function accept(file){if(importBusy)return;importBusy=true;status.textContent='Reading the sheet locally…';try{const ext=file.name.split('.').at(-1).toLowerCase();if(file.size>(ext==='pdf'?20_000_000:2_000_000))throw Error('File is too large. Export a single character sheet.');if(ext==='pdf')candidates=await parsePDF(await file.arrayBuffer());else{const text=await file.text();if(ext==='xml')candidates=parseXML(text);else if(['csv','tsv'].includes(ext))candidates=parseSheet(text);else if(ext==='json'){candidates=parseCharacterJSON(text);}else candidates=parseText(text);}for(const c of candidates)c.provenance={...c.provenance,filename:file.name};if(!candidates.length)throw Error('No character rows found.');draft=clone(candidates[0]);placementSide=draft.kind==='npc'?'foe':'friend';builderErrors=[];show('review');}catch(e){fail(e);}finally{importBusy=false;}}
 function drawImport(){para(main,'Files are read in your browser. They are not uploaded to an AI service. XML includes common Fantasy Grounds character exports; PDFs can have form fields or readable text. Every import goes through review.');const picker=field(main,'Choose XML, PDF, CSV/TSV, text or Isles JSON','',()=>{}, {type:'file'});picker.accept='.xml,.pdf,.csv,.tsv,.txt,.json';picker.onchange=()=>{if(picker.files[0])accept(picker.files[0]);};
 const sheet=section(main,'Google Sheets');para(sheet,'For a private sheet: copy the character cells and paste below, or use File → Download → Comma-separated values (.csv). This app does not request access to your Google account.');let url='';field(sheet,'Public Google Sheets link','',v=>url=v,{type:'url'});sheet.append(button('Read public sheet',async()=>{try{status.textContent='Reading the public sheet…';const response=await fetch(sheetsCSVURL(url),{credentials:'omit',signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error('The sheet cannot be read. Export CSV or paste the cells instead.');const text=await response.text();if(/^\s*</.test(text))throw Error('The sheet returned a sign-in page. Export CSV or paste the cells instead.');candidates=parseSheet(text);if(!candidates.length)throw Error('No rows found.');draft=clone(candidates[0]);placementSide=draft.kind==='npc'?'foe':'friend';builderErrors=[];show('review');}catch(e){fail(Error('Could not read that public sheet. Export CSV or paste cells below. '+e.message));}}));
 let pasted='';field(main,'Paste copied spreadsheet cells or labeled sheet text','',v=>pasted=v,{type:'textarea',rows:7});para(main,'Supported layouts: a two-column Field / Value sheet; a table with headers such as Name, Class, Level, STR, DEX, HPMax, AC, Speed, AttackBonus, Damage, DamageBonus; or lines such as “Armor Class: 16”.');main.append(button('Parse pasted cells / text',()=>{try{candidates=pasted.includes('\t')||pasted.split('\n')[0].includes(',')?parseSheet(pasted):parseText(pasted);draft=clone(candidates[0]);placementSide=draft.kind==='npc'?'foe':'friend';builderErrors=[];show('review');}catch(e){fail(e);}}));para(main,'Image-only scans need OCR first. PDF layouts and vendor XML schemas vary; unmapped fields are preserved in the source extract and need manual review.');}
